const portfolio = Number(retirementPortfolio) || 0;
const rate = Number(annualWithdrawalRate) || 0;
const ret = Number(expectedAnnualReturn) || 0;
const years = Number(retirementYears) || 1;
const annualWithdrawal = portfolio * (rate / 100);
const monthlyWithdrawal = annualWithdrawal / 12;
const realGrowth = ret - rate;
let bal = portfolio;
let depleted = years;
let survived = true;
for (let y = 1; y <= years; y++) {
  bal = bal * (1 + ret / 100) - annualWithdrawal;
  if (bal <= 0) { depleted = y; survived = false; break; }
}
const endBalance = survived ? bal : 0;
return { withdrawalRate: rate, annualWithdrawal, monthlyWithdrawal, endBalance };
